function resources(values){return RESOURCES.map(r=>{const v=values[r.id],state=v<30?"low":v<70?"warning":"healthy";return'<div class="resource"><label>'+(ar()?r.ar:r.name)+'</label><div class="bar"><i class="'+state+'" style="width:'+v+'%"></i></div><b>'+v+'</b></div>';}).join("");}
function resourceSummary(values){const groups=[["power",local("ENERGY","الطاقة"),"⚡",values.power],["oxygen",local("OXYGEN","الأكسجين"),"◉",values.oxygen],["supplies",local("WATER & FOOD","المياه والغذاء"),"◈",Math.round((values.water+values.food)/2)],["shield",local("RADIATION PROTECTION","الحماية من الإشعاع"),"🛡️",values.shield]];return '<div class="resource-summary">'+groups.map(([id,label,icon,value])=>'<div class="resource-tile"><span>'+icon+'</span><div><small>'+label+'</small><b>'+value+'%</b><div class="bar"><i class="'+(value<30?"low":value<70?"warning":"healthy")+'" style="width:'+value+'%"></i></div></div></div>').join("")+'</div>';}


const OXYGEN_CHECK_QUESTIONS=[
 {en:"The reference life-support budget lists about 0.84 kg of oxygen per person per day. What does this describe?",ar:"تذكر ميزانية دعم الحياة المرجعية نحو 0.84 كجم أكسجين للفرد يوميًا. إلى ماذا يشير الرقم؟",enOptions:["An average daily habitat life-support requirement","The total oxygen carried in one spacesuit","The pressure inside a spacesuit"],arOptions:["احتياجًا يوميًا مرجعيًا متوسطًا لدعم الحياة للفرد","إجمالي الأكسجين المحمول في بدلة واحدة","ضغط الهواء داخل بدلة الفضاء"],answer:0,enExplain:"Correct. This is a planning value for one crew member-day, not a suit tank size or live sensor reading.",arExplain:"صحيح. ده رقم مرجعي للتخطيط لاحتياج فرد خلال يوم، مش سعة خزان البدلة ولا قراءة مستشعر مباشر."},
 {en:"NASA describes the ISS EMU spacesuit operating at about 4.2 psi with a pure-oxygen atmosphere. Which statement is best?",ar:"تصف ناسا بدلة EMU بمحطة الفضاء بأنها تعمل عند نحو 4.2 psi وبجو من الأكسجين النقي. أي عبارة أدق؟",enOptions:["It is a suit-specific design condition, not habitat pressure","Every spacecraft habitat should use the same pressure","The number tells us how many hours oxygen will last"],arOptions:["ده شرط تصميم خاص بالبدلة، وليس ضغط القاعدة السكنية","كل قاعدة فضائية لازم تستخدم الضغط نفسه","الرقم ده بيحدد عدد ساعات كفاية الأكسجين"],answer:0,enExplain:"Correct. Suit pressure and habitat pressure are different. EVA duration depends on the suit and mission; 6.5–8 hours is not a universal guarantee.",arExplain:"صحيح. ضغط البدلة يختلف عن ضغط القاعدة. مدة السير الفضائي تعتمد على البدلة والمهمة، لذلك 6.5–8 ساعات ليست ضمانًا ثابتًا."},
 {en:"SCENARIO: A lunar habitat houses four astronauts. The oxygen supply is lower than expected and may not last the next two days at the current consumption rate. What should you do?",ar:"سيناريو: قاعدة قمرية يقيم بها أربعة رواد فضاء. مخزون الأكسجين أقل من المتوقع وقد لا يكفي اليومين القادمين بمعدل الاستهلاك الحالي. ماذا تفعل؟",enOptions:["A. Ignore the warning and continue all activities normally.","B. Review oxygen consumption, postpone non-essential activities, and activate the mission's backup plan.","C. Reduce the cabin oxygen percentage without checking safety limits.","D. Continue the mission without monitoring oxygen levels."],arOptions:["أ. تجاهل التحذير والاستمرار في كل الأنشطة بشكل طبيعي.","ب. مراجعة استهلاك الأكسجين، وتأجيل الأنشطة غير الضرورية، وتفعيل خطة الاحتياط للمهمة.","ج. خفض نسبة الأكسجين في القاعدة دون التحقق من حدود السلامة.","د. مواصلة المهمة دون مراقبة مستويات الأكسجين."],answer:1,enExplain:"Correct. Monitoring consumption, postponing non-essential activity and following the approved backup plan helps preserve the simulated reserve. Cabin oxygen must never be adjusted outside approved safety limits. Game impact: the simulation applies its backup-reserve response, reduces optional consumption, and awards Resource Management points.",arExplain:"صحيح. متابعة الاستهلاك وتأجيل الأنشطة غير الضرورية واتباع خطة الاحتياط المعتمدة يساعد على الحفاظ على المخزون الافتراضي. لا يجوز تغيير نسبة الأكسجين داخل القاعدة خارج حدود السلامة المعتمدة. تأثير اللعبة: تفعيل استجابة الاحتياطي الافتراضية وتقليل الاستهلاك الاختياري وكسب نقاط إدارة الموارد."}
];
function oxygenKnowledgePanel(m){
 if(!resourceAlerts(m).some(x=>x.id==="oxygen"))return "";
 const answers=s.oxygenQuizAnswers??(s.oxygenQuizAnswers={});
 const questions=OXYGEN_CHECK_QUESTIONS.map((q,index)=>{
  const chosen=answers[String(m.day)+":"+index];
  const options=(ar()?q.arOptions:q.enOptions).map((label,i)=>'<button type="button" class="oxygen-quiz-option '+(chosen===i?(i===q.answer?"correct":"incorrect"):"")+'" data-action="oxygen-quiz" data-question="'+index+'" data-answer="'+i+'">'+esc(label)+'</button>').join("");
  const feedback=chosen===undefined?"":'<p class="oxygen-quiz-feedback '+(chosen===q.answer?"correct":"incorrect")+'">'+(chosen===q.answer?"✓ ":"↻ ")+esc(ar()?q.arExplain:q.enExplain)+'</p>';
  return '<article class="oxygen-quiz-question"><b>'+(index+1)+'. '+esc(ar()?q.ar:q.en)+'</b><div class="oxygen-quiz-options">'+options+'</div>'+feedback+'</article>';
 }).join("");
 return '<section class="oxygen-learning-card"><div class="oxygen-learning-heading"><span>🫧</span><div><b>'+local("OXYGEN KNOWLEDGE CHECK","اختبار معرفة الأكسجين")+'</b><small>'+local("Learn the science before choosing a game response.","اتعلم المعلومة العلمية قبل اختيار استجابة اللعبة.")+'</small></div></div><div class="oxygen-facts"><p><b>0.84 kg / person-day</b> · '+local("Reference daily oxygen requirement for life-support planning.","احتياج يومي مرجعي للأكسجين في تخطيط دعم الحياة.")+'</p><p><b>≈ 4.2 psi (≈ 0.29 bar)</b> · '+local("NASA reference for the ISS EMU suit atmosphere; not habitat pressure.","مرجع ضغط جو بدلة EMU بمحطة الفضاء؛ وليس ضغط القاعدة السكنية.")+'</p></div>'+questions+'<small class="oxygen-source-note">'+local("Sources: ","المصادر: ")+'<a href="https://ntrs.nasa.gov/api/citations/20210013975/downloads/Life%20Support%20Presentation%20to%20Space%20Portal%2004_21_2021%20V2.pdf" target="_blank" rel="noopener noreferrer">NASA Life Support Requirements</a> · <a href="https://www.nasa.gov/wp-content/uploads/2023/12/ochmo-tb-002-eclss.pdf" target="_blank" rel="noopener noreferrer">NASA OCHMO ECLSS</a>. '+local("Suit duration varies by system and mission.","مدة استخدام البدلة تختلف حسب النظام والمهمة.")+'</small></section>';
}


const WATER_CHECK_QUESTIONS=[
 {en:"NASA's hydration planning minimum is 2.5 L of potable water per crewmember per day. What is included?",ar:"الحد الأدنى المرجعي من ناسا لمياه الترطيب هو 2.5 لتر من المياه الصالحة للشرب لكل فرد يوميًا. ما الذي يشمله؟",enOptions:["Drinking water and water to rehydrate food and drinks","All water for drinking, hygiene, agriculture and every system","Untreated wastewater"],arOptions:["مياه الشرب والمياه المستخدمة لإعادة ترطيب الطعام والمشروبات","كل مياه الشرب والنظافة والزراعة وجميع الأنظمة","مياه الصرف غير المعالجة"],answer:0,enExplain:"Correct. This hydration allocation includes drinking and rehydrating food or beverages. Personal hygiene and other mission uses are separate requirements.",arExplain:"صحيح. مخصص الترطيب يشمل الشرب وإعادة ترطيب الطعام أو المشروبات. أما النظافة الشخصية واستخدامات المهمة الأخرى فلها متطلبات منفصلة."},
 {en:"Why must untreated wastewater remain separate from potable water?",ar:"ليه لازم مياه الصرف غير المعالجة تفضل منفصلة عن مياه الشرب؟",enOptions:["It may contain contaminants and needs an approved treatment process","All wastewater is immediately safe to drink","Recycling systems always recover 100%"],arOptions:["لأنها قد تحتوي على ملوثات وتحتاج إلى معالجة معتمدة","لأن كل مياه الصرف صالحة للشرب فورًا","لأن أنظمة الاستعادة تسترجع المياه بنسبة 100% دائمًا"],answer:0,enExplain:"Correct. Water recovery uses multiple treatment and monitoring steps. Recovered water quality must be verified; untreated wastewater is not potable.",arExplain:"صحيح. استعادة المياه تعتمد على مراحل معالجة ومراقبة متعددة. يجب التحقق من جودة المياه المستعادة؛ ومياه الصرف غير المعالجة ليست صالحة للشرب."},
 {en:"SCENARIO: The habitat's potable water supply is decreasing faster than expected, while the recycling system is less efficient than planned. What is the best decision?",ar:"سيناريو: مخزون مياه الشرب في القاعدة بينخفض أسرع من المتوقع، ونظام إعادة تدوير المياه كفاءته أقل من المخطط. ما أفضل قرار؟",enOptions:["A. Stop drinking water to save the remaining supply.","B. Monitor potable water levels, inspect the recycling system, and postpone non-essential water use.","C. Drink untreated wastewater directly.","D. Assume all wastewater can be recycled immediately."],arOptions:["أ. التوقف عن شرب المياه لتوفير الكمية المتبقية.","ب. متابعة مستوى مياه الشرب، وفحص نظام الاستعادة، وتأجيل استخدامات المياه غير الضرورية.","ج. شرب مياه الصرف غير المعالجة مباشرةً.","د. افتراض إمكانية إعادة تدوير كل مياه الصرف فورًا."],answer:1,enExplain:"Correct. Track the potable reserve, check the simulated recovery loop and defer optional demand. Never assume 100% recovery or treat untreated wastewater as drinking water. Game impact: the simulation improves its water-recovery reserve while using power.",arExplain:"صحيح. تابع مخزون مياه الشرب، وافحص دورة الاستعادة الافتراضية، وأجّل الاستخدامات الاختيارية. لا تفترض استعادة 100% من المياه ولا تعتبر مياه الصرف غير المعالجة صالحة للشرب. تأثير اللعبة: تتحسن كمية المياه في المحاكاة مع استهلاك جزء من الطاقة."}
];
